/**
 * 解析 - Diun
 */

// ======================= 可配置图标 =======================
// Docker Hub 镜像更新通知图标（如需外网展示，可改为你的公网 自建图床 图床地址）
const DIUN_DOCKER_ICON = "https://cdn.jsdelivr.net/gh/selfhst/icons/png/docker.png";
// 非 Docker Hub 镜像（如 ghcr.io / lscr.io）的默认图标（留空则不设图标）
const DIUN_DEFAULT_ICON = "";
// =========================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));
let testMode = false;
const bark = (group, title, body, extra = {}) => {
    const payload = { group, title: testMode ? `【🧪测试】 ${title}` : title, body, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    return payload;
};

// 时间统一按 UTC+8 显示，不依赖 n8n 容器的 TZ 设置
const formatDiunDate = (value) => {
    const text = str(value).trim();
    if (!text) return "";
    const d = new Date(text);
    if (Number.isNaN(d.getTime())) return text;
    const hasZone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(text);
    const t = hasZone ? new Date(d.getTime() + 8 * 3600 * 1000) : d;
    const year = hasZone ? t.getUTCFullYear() : t.getFullYear();
    const month = hasZone ? t.getUTCMonth() + 1 : t.getMonth() + 1;
    const day = hasZone ? t.getUTCDate() : t.getDate();
    const hour = hasZone ? t.getUTCHours() : t.getHours();
    const minute = hasZone ? t.getUTCMinutes() : t.getMinutes();
    const p = (n) => String(n).padStart(2, "0");
    return `${year}/${p(month)}/${p(day)} ${p(hour)}:${p(minute)}`;
};

const { kind, payload } = $input.first().json;
testMode = payload.__test === true;
if (kind !== "diun") return [];

const image = str(payload.image);
const parts = image.split("/").reverse();
const registryPart = parts[1] || "";
const repoPart = str(parts[0]).split(":")[0];
const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const title = `🐳 ${val(`${registryPart}/${repoPart}`)} 有新版本发布`;
const body =
    `【发布平台】${val(payload.provider)}\n` +
    `【镜像】${val(image)}\n` +
    `【更新时间】${val(formatDiunDate(payload.created))}\n` +
    `【支持架构】${val(payload.platform)}\n` +
    `【唯一标识】${val(payload.digest)}\n` +
    `【抓取列表】${val(payload.mime_type)}\n` +
    `【Diun 版本】${val(payload.diun_version)}\n\n` +
    (image.includes("docker.io") ? `🔗在DockerHub中查看🔗 ${val(payload.hub_link)}` : DASH);

return [
    {
        json: {
            bark: bark("Diun", title, body, {
                icon: image.includes("docker.io") ? DIUN_DOCKER_ICON : DIUN_DEFAULT_ICON
            }),
            source: "Diun"
        }
    }
];
